when (response.code) {
    in 200..299 -> decodeSuccess(response)
    401 -> ApiResult.AuthenticationRequired
    404 -> ApiResult.NotFound
    429 -> ApiResult.RetryLater(response.retryAfter)
    in 500..599 -> ApiResult.ServerFailure(response.code)
    else -> ApiResult.Unexpected(response.code)
}

@Serializable
data class ExpenseDto(val id: String?, val amountMinor: Long?)

fun ExpenseDto.toDomain(): Expense {
    val safeId = id?.takeIf { it.isNotBlank() } ?: error("Missing id")
    val minor = requireNotNull(amountMinor) { "Missing amount" }
    require(minor >= 0) { "Negative amount" }
    return Expense(ExpenseId(safeId), Money(minor))
}

