data class ExpenseDto(val id: String?, val amountMinor: Long?)
data class Expense(val id: String, val amountMinor: Long)
fun ExpenseDto.toDomainOrNull(): Expense? {
    val safeId = id?.trim()?.takeIf { it.isNotEmpty() } ?: return null
    val safeAmount = amountMinor?.takeIf { it >= 0 } ?: return null
    return Expense(safeId, safeAmount)
}
